  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.word { font-size: 28px; font-weight: 700; color: #f8fafc; margin-bottom: 6px; }
.verb { font-size: 32px; font-weight: 700; color: #f8fafc; margin-bottom: 4px; }
.meaning { font-size: 20px; color: #a5f3fc; margin-bottom: 8px; }
.grammar { font-size: 15px; color: #94a3b8; font-style: italic; margin-bottom: 4px; }
.plural { font-size: 15px; color: #94a3b8; margin-bottom: 4px; }
.plural b { color: #64748b; font-weight: 600; font-style: normal; }
.translation { font-size: 22px; color: #e0e7ff; margin: 10px 0; }
.verb-forms { font-size: 14px; color: #94a3b8; margin-top: 4px; }
.question { font-size: 24px; font-weight: 600; color: #f8fafc; margin-bottom: 12px;
            line-height: 1.4; max-width: 600px; }
.answer { font-size: 22px; color: #a5f3fc; font-weight: 600; margin: 12px 0;
          max-width: 600px; line-height: 1.4; }
/* Unified CEFR/level badge across all card types */
.level, .tag {
  display: inline-block; font-size: 12px; color: #8b5cf6; font-weight: 600;
  letter-spacing: 0.5px; text-transform: uppercase;
  padding: 3px 10px; border: 1px solid rgba(139, 92, 246, 0.3);
  border-radius: 10px; margin: 4px 2px;
}
.section { text-align: left; max-width: 560px; width: 100%; margin-top: 10px; }
.section-title { font-size: 13px; color: #64748b; text-transform: uppercase;
                 letter-spacing: 1px; margin: 12px 0 4px 0; }
.info { font-size: 16px; color: #cbd5e1; line-height: 1.6; padding: 2px 0; }
.info b { color: #e0e7ff; }
.examples { text-align: left; margin-top: 10px; max-width: 560px; }
.example.phrase { font-style: normal; color: #a5b4fc; }
.example { font-size: 16px; color: #cbd5e1; font-style: italic; padding: 10px 16px;
           background: rgba(255, 255, 255, 0.05); border-left: 3px solid #8b5cf6;
           border-radius: 0 8px 8px 0; margin-top: 8px; line-height: 1.5; }
.conj-table { width: 100%; border-collapse: collapse; margin-top: 6px; }
.conj-table td { padding: 3px 8px; font-size: 15px; color: #cbd5e1; }
.conj-table td:first-child { color: #64748b; width: 50px; }
hr { border: none; border-top: 1px solid rgba(148, 163, 184, 0.2); margin: 14px 0; width: 80%; }
